namespace Bazaar.Server.Council.Service;

/// <summary>
/// A vote as stored (council_vote, docs/design/10-council-and-voting.md, Data and interfaces). Pure data; the store maps it.
/// </summary>
/// <param name="VoteId">Vote id. Generated by the service.</param>
/// <param name="GcId">The GC the vote runs in.</param>
/// <param name="SubjectRef">What the vote is about (a task, a hire candidate, a Constitution clause, and so on).</param>
/// <param name="Kind">Ballot shape.</param>
/// <param name="MotionClass">Ordinary or bigger change, fixed at open.</param>
/// <param name="State">Current lifecycle state.</param>
/// <param name="Version">Row version for optimistic concurrency. Starts at 1 and rises by one per transition.</param>
/// <param name="Options">Option ids for option choice; empty for approve/reject.</param>
/// <param name="DeadlineAt">Current deadline, moved by an extension.</param>
/// <param name="Extensions">Extensions already used.</param>
/// <param name="EligibleVoterIds">Eligible electorate, snapshotted at open.</param>
/// <param name="ProposerId">The agent that opened the vote.</param>
/// <param name="SubjectAuthorId">The subject's author, excluded from voting when council.exclude_author is set.</param>
/// <param name="RevealSeed">Seed for the stored, randomised reason order (council.reason_order).</param>
/// <param name="VaultDecisionNo">NNNN of the decision file, once written; null before.</param>
/// <param name="CreatedAt">When the vote opened.</param>
public sealed record CouncilVoteRecord(
    Guid VoteId,
    Guid GcId,
    string SubjectRef,
    VoteKind Kind,
    MotionClass MotionClass,
    VoteState State,
    long Version,
    IReadOnlyList<string> Options,
    DateTimeOffset DeadlineAt,
    int Extensions,
    IReadOnlySet<string> EligibleVoterIds,
    string ProposerId,
    string? SubjectAuthorId,
    long RevealSeed,
    int? VaultDecisionNo,
    DateTimeOffset CreatedAt);

/// <summary>
/// One stored ballot (council_ballot, one row per voter and phase). Reasoning is plaintext here; the store encrypts it
/// with the voter's per-person key (doc 04) and decrypts it on read.
/// </summary>
/// <param name="VoteId">The vote.</param>
/// <param name="VoterId">The voter's agent id.</param>
/// <param name="Phase">Independent or follow-up.</param>
/// <param name="Choice">An approve/reject choice or one of the vote's options.</param>
/// <param name="Reasoning">Stated reasoning.</param>
/// <param name="TaintedAtWrite">Whether the voter's session was tainted when the ballot was written (doc 15).</param>
/// <param name="SubmittedAt">When the ballot was written.</param>
public sealed record StoredBallot(
    Guid VoteId,
    string VoterId,
    BallotPhase Phase,
    string Choice,
    string Reasoning,
    bool TaintedAtWrite,
    DateTimeOffset SubmittedAt);

/// <summary>
/// Storage port for the Council service. Implemented over Postgres by the store (WP3); the service and its tests use fakes.
/// Every write that changes vote state is a single transaction that also appends council_transition.
/// </summary>
public interface ICouncilStore
{
    /// <summary>Loads a vote, or null when it does not exist.</summary>
    Task<CouncilVoteRecord?> FindVoteAsync(Guid voteId, CancellationToken ct);

    /// <summary>Inserts a vote in state Collecting and its first transition (null to Collecting, reason "open").</summary>
    Task InsertVoteAsync(CouncilVoteRecord vote, CancellationToken ct);

    /// <summary>
    /// Moves a vote to <paramref name="target"/> only when its version still equals <paramref name="expectedVersion"/>.
    /// Sets version to expectedVersion + 1 and any given extension count or deadline. Returns false on a version mismatch.
    /// </summary>
    Task<bool> TryTransitionAsync(
        Guid voteId,
        long expectedVersion,
        VoteState target,
        string reason,
        DateTimeOffset at,
        DateTimeOffset? newDeadlineAt,
        int? newExtensions,
        CancellationToken ct);

    /// <summary>Sets the vault decision number on a vote. Idempotent when the same number is already set.</summary>
    Task SetVaultDecisionNoAsync(Guid voteId, int decisionNo, CancellationToken ct);

    /// <summary>All ballots for a vote, both phases, in submit order.</summary>
    Task<IReadOnlyList<StoredBallot>> ListBallotsAsync(Guid voteId, CancellationToken ct);

    /// <summary>
    /// Inserts a ballot for (vote, voter, phase). Returns false when that phase already has a ballot for the voter;
    /// the caller decides whether that is a rejection (independent) or a change (follow-up versions are kept in the store).
    /// </summary>
    Task<bool> TryInsertBallotAsync(StoredBallot ballot, CancellationToken ct);
}

/// <summary>
/// Port to the GC log (docs/design/01). The adapter wraps <c>IGcLogWriter</c>; the service only needs this narrow shape.
/// Idempotent by <paramref name="idempotencyKey"/>, so a retried service call appends nothing twice.
/// </summary>
public interface ICouncilGcEvents
{
    /// <summary>Appends a <c>council.*</c> event (open, reveal, transition or decision) to the vote's GC.</summary>
    Task AppendAsync(Guid gcId, string kind, string payloadJson, string idempotencyKey, CancellationToken ct);
}

/// <summary>
/// Port to the Vault decision writer (doc 18). Writes <c>decisions/NNNN-slug.md</c> and returns NNNN. Implemented by the
/// Vault adapter (WP7, not in this group); the service only calls it when a decision is recorded.
/// </summary>
public interface ICouncilDecisionWriter
{
    /// <summary>Writes the decision file for a decided or owner-resolved vote and returns its number.</summary>
    Task<int> WriteDecisionAsync(Guid voteId, string slug, string markdownBody, CancellationToken ct);
}
